    setState(loadDemoStore().events.some((e) => e.id === id) ? "found" : "missing");
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [id]);

  if (state === "missing")
    return (
      <div className="mx-auto max-w-3xl px-4 pt-14">
