1	"use client";
2	
3	import type { Meeting, Upcoming } from "@/lib/model";
4	import { SpeakingGraph } from "@/components/SpeakingGraph";
5	import { mmss, fmtTime, hms } from "@/lib/time";
6	import Link from "next/link";
7	import { useEffect, useRef, useState } from "react";
8	
9	/** Real-time milliseconds between streamed utterances (accelerated clock). */
10	const TICK_MS = 1400;
11	/** Acceleration label — sim clock runs this many seconds per real second. */
12	const SPEED = 20;
13	
14	/**
15	 * Live capture simulation. This build stubs the capture layer; this screen plays
16	 * the part of the local-recording flow — elapsed clock, streaming words, the
17	 * speaking graph growing in real time — and lands on the summary Minutes writes
18	 * when the call ends.
19	 */
20	export function LiveCapture({
21	  event,
22	  meeting,
23	  onDone,
24	}: {
25	  event: Upcoming;
26	  meeting: Meeting;
27	  /** fired once when the simulated call ends — where a booked call gets recorded */
28	  onDone?: () => void;
29	}) {
30	  const [phase, setPhase] = useState<"armed" | "live" | "done">("armed");
31	  const [turns, setTurns] = useState(0);
32	  const [simSec, setSimSec] = useState(0);
33	  const [words, setWords] = useState(0);
34	  const [fastForwarding, setFastForwarding] = useState(false);
35	  const listRef = useRef<HTMLDivElement>(null);
36	
37	  // the accelerated capture clock
38	  useEffect(() => {
39	    if (phase !== "live") return;
40	    const timer = setInterval(() => {
41	      setSimSec((s) => s + SPEED / 2);
42	      setWords((w) => w + 11);
43	    }, 500);
44	    return () => clearInterval(timer);
45	  }, [phase]);
46	
47	  // stream utterances in
48	  useEffect(() => {
49	    if (phase !== "live" || fastForwarding) return;
50	    if (turns >= meeting.transcript.length) {
51	      setPhase("done");
52	      return;
53	    }
54	    const t = setTimeout(() => setTurns((n) => n + 1), TICK_MS);
55	    return () => clearTimeout(t);
56	  }, [phase, turns, fastForwarding, meeting.transcript.length]);
57	
58	  // auto-scroll the streaming transcript
59	  useEffect(() => {
60	    listRef.current?.scrollTo({ top: listRef.current.scrollHeight, behavior: "smooth" });
61	  }, [turns]);
62	
63	  // the call ended: hand the recording to whoever armed the capture
64	  useEffect(() => {
65	    if (phase === "done") onDone?.();
66	    // eslint-disable-next-line react-hooks/exhaustive-deps
67	  }, [phase]);
68	
69	  function start() {
70	    setPhase("live");
71	  }
72	
73	  function endNow() {
74	    setFastForwarding(true);
75	    setTurns(meeting.transcript.length);
76	    setSimSec(meeting.duration);
77	    setPhase("done");
78	  }
79	
80	  const shown = meeting.transcript.slice(0, turns);
81	  const speakerOf = (id: string) => meeting.speakers.find((s) => s.id === id);
82	  const summary = meeting.summaries[meeting.defaultTemplate];
83	  const startAt = new Date(event.startedAt);
84	  const liveClock = new Date(startAt.getTime() + simSec * 1000);
85	
86	  return (
87	    <div className="mx-auto max-w-3xl px-4 pb-16 pt-8 sm:px-6">
88	      {/* ── header ─────────────────────────────────────────────────── */}
89	      <div className="mb-5 flex flex-wrap items-start justify-between gap-3">
90	        <div>
91	          <p className="eyebrow mb-1">
92	            {event.platform} · starts {fmtTime(event.startedAt)}
93	          </p>
94	          <h1 className="font-[family-name:var(--font-display)] text-3xl font-medium tracking-tight">
95	            {event.title}
96	          </h1>
97	        </div>
98	        <span
99	          className={
100	            "rounded-full px-2.5 py-1 text-[12.5px] font-medium " +
101	            (event.captureMode === "bot"
102	              ? "bg-line-soft text-ink-soft"
103	              : "bg-ok-soft text-ok")
104	          }
105	        >
106	          {event.captureMode === "bot" ? "minutes bot joins" : "bot-free — captures locally"}
107	        </span>
108	      </div>
109	
110	      {phase === "armed" && (
111	        <div className="pane p-6">
112	          <p className="text-[15px] leading-relaxed text-ink-soft">
113	            Minutes is armed for this call.
114	            {event.captureMode === "bot"
115	              ? " The notetaker bot will join as a visible participant when the meeting starts."
116	              : " No bot joins — Minutes records your system audio and microphone from your machine."}
117	          </p>
118	          <div className="mt-5 flex flex-wrap items-center gap-3">
119	            <button
120	              onClick={start}
121	              className="rounded-full bg-ink px-5 py-2.5 text-[14px] font-medium text-paper hover:opacity-90"
122	            >
123	              ▶ Simulate the call starting
124	            </button>
125	            <Link href="/" className="text-[13.5px] text-ink-soft hover:text-ink">
126	              Back to meetings
127	            </Link>
128	          </div>
129	          <p className="mt-4 text-[12.5px] text-ink-faint">
130	            This walkthrough build stubs the capture layer — the simulation below shows what a
131	            real session looks like from your seat.
132	          </p>
133	        </div>
134	      )}
135	
136	      {phase === "live" && (
137	        <div>
138	          {/* status bar */}
139	          <div className="pane flex flex-wrap items-center gap-x-4 gap-y-1 px-4 py-3">
140	            <span className="flex items-center gap-2 text-[13.5px] font-medium">
141	              <span className="rec-dot size-2 rounded-full bg-record" aria-hidden />
142	              Capturing
143	            </span>
144	            <span className="font-mono text-[13.5px] tabular-nums text-ink">
145	              {mmss(Math.floor(simSec))}
146	            </span>
147	            <span className="text-[12.5px] text-ink-faint">
148	              {words.toLocaleString()} words ·{" "}
149	              {liveClock.toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" })}
150	            </span>
151	            <button
152	              onClick={endNow}
153	              className="ml-auto rounded-full border border-line bg-raised px-3.5 py-1.5 text-[12.5px] font-medium text-ink-soft hover:border-ink-soft hover:text-ink"
154	            >
155	              Jump to call end ⏭
156	            </button>
157	          </div>
158	
159	          {/* growing speaking graph */}
160	          <div className="pane mt-4 px-4 pt-3 pb-1" aria-hidden>
161	            <SpeakingGraph
162	              meeting={{ ...meeting, transcript: shown }}
163	              progress={simSec / meeting.duration}
164	              height={44}
165	            />
166	          </div>
167	
168	          {/* streaming transcript */}
169	          <div
170	            ref={listRef}
171	            className="pane mt-4 h-72 overflow-y-auto"
172	            aria-label="Streaming transcript"
173	          >
174	            <ul>
175	              {shown.map((u, i) => {
176	                const sp = speakerOf(u.speaker);
177	                return (
178	                  <li key={i} className="border-b border-line-soft px-4 py-2.5">
179	                    <div className="mb-0.5 flex items-baseline gap-2">
180	                      <span
181	                        className="text-[12.5px] font-semibold"
182	                        style={{ color: sp?.self ? undefined : sp?.color }}
183	                      >
184	                        {sp?.self ? "You" : sp?.name}
185	                      </span>
186	                    </div>
187	                    <p className="text-[14px] leading-relaxed text-ink-soft">{u.text}</p>
188	                  </li>
189	                );
190	              })}
191	            </ul>
192	          </div>
193	          <p className="mt-2 text-right text-[12px] text-ink-faint">
194	            capture simulation, ~{SPEED}× speed
195	          </p>
196	        </div>
197	      )}
198	
199	      {phase === "done" && summary && (
200	        <div>
201	          <div className="pane flex items-center gap-3 px-4 py-3">
202	            <span className="rec-dot size-2 rounded-full bg-record" aria-hidden />
203	            <span className="text-[14px] font-medium">Call ended</span>
204	            <span className="font-mono text-[13px] tabular-nums text-ink-faint">
205	              {hms(meeting.duration)} captured
206	            </span>
207	          </div>
208	          <div className="pane mt-4 p-5">
209	            <p className="eyebrow mb-2">Minutes wrote, as the call ended</p>
210	            <p className="font-[family-name:var(--font-display)] text-xl leading-snug">
211	              {summary.gist}
212	            </p>
213	            <ul className="mt-4 space-y-2.5">
214	              {summary.sections[0]?.bullets.slice(0, 4).map((b, i) => (
215	                <li key={i} className="flex gap-2.5 text-[14px] leading-relaxed">
216	                  <span className="text-ink-faint">·</span>
