1	"use client";
2	
3	import type { Meeting } from "@/lib/model";
4	import { dealForMeeting } from "@/lib/data";
5	import { usePlayer } from "@/lib/player";
6	import { Player } from "./Player";
7	import { TranscriptPane } from "./TranscriptPane";
8	import { LeftPanel } from "./LeftPanel";
9	import { ChatPanel } from "./ChatPanel";
10	import { fmtDate, fmtTime, hms } from "@/lib/time";
11	import Link from "next/link";
12	import { useEffect, useState } from "react";
13	
14	export function MeetingView({ meeting, initialTime }: { meeting: Meeting; initialTime: number }) {
15	  const player = usePlayer(meeting, initialTime);
16	  const [copiedLink, setCopiedLink] = useState(false);
17	  const [chatOpen, setChatOpen] = useState(false);
18	
19	  // keyboard: space = play/pause, arrows seek, Escape closes chat (when not typing)
20	  useEffect(() => {
21	    function onKey(e: KeyboardEvent) {
22	      const tag = (e.target as HTMLElement)?.tagName;
23	      if (tag === "INPUT" || tag === "TEXTAREA" || tag === "SELECT") {
24	        if (e.key === "Escape") {
25	          (e.target as HTMLElement).blur();
26	          setChatOpen(false);
27	        }
28	        return;
29	      }
30	      if (e.code === "Space") {
31	        e.preventDefault();
32	        player.toggle();
33	      }
34	      if (e.key === "ArrowRight") player.seek(player.t + 10);
35	      if (e.key === "ArrowLeft") player.seek(player.t - 10);
36	      if (e.key === "Escape") setChatOpen(false);
37	    }
38	    window.addEventListener("keydown", onKey);
39	    return () => window.removeEventListener("keydown", onKey);
40	  }, [player]);
41	
42	  async function copyAtCurrentTime() {
43	    const url = `${window.location.origin}/m/${meeting.id}?t=${Math.floor(player.t)}`;
44	    try {
45	      await navigator.clipboard.writeText(url);
46	      setCopiedLink(true);
47	      setTimeout(() => setCopiedLink(false), 2000);
48	    } catch {
49	      setCopiedLink(false);
50	    }
51	  }
52	
53	  const others = meeting.speakers.filter((s) => !s.self);
54	  const deal = dealForMeeting(meeting.id);
55	
56	  return (
57	    <div className="mx-auto max-w-6xl px-4 pb-16 pt-8 sm:px-6">
58	      {/* ── header ─────────────────────────────────────────────────────── */}
59	      <div className="mb-6 flex flex-wrap items-start justify-between gap-4">
60	        <div className="min-w-0">
61	          <h1 className="font-[family-name:var(--font-display)] text-[32px] font-medium leading-tight tracking-tight">
62	            {meeting.title}
63	          </h1>
64	          <div className="mt-2 flex flex-wrap items-center gap-x-3 gap-y-1 text-[13.5px] text-ink-soft">
65	            <span>
66	              {fmtDate(meeting.startedAt)} · {fmtTime(meeting.startedAt)}
67	            </span>
68	            <span className="font-mono tabular-nums text-ink-faint">{hms(meeting.duration)}</span>
69	            <span>{meeting.platform}</span>
70	            <span
71	              className={
72	                "rounded-full px-2 py-0.5 text-[11.5px] font-medium " +
73	                (meeting.captureMode === "bot"
74	                  ? "bg-line-soft text-ink-soft"
75	                  : "bg-ok-soft text-ok")
76	              }
77	            >
78	              {meeting.captureMode === "bot" ? "bot recorded" : "bot-free capture"}
79	            </span>
80	            {deal && (
81	              <Link
82	                href={`/deal/${deal.id}`}
83	                className="rounded-full bg-record-soft px-2 py-0.5 text-[11.5px] font-medium text-record hover:bg-record hover:text-paper"
84	                title="This call is one of the calls in this deal's room"
85	              >
86	                Deal room · {deal.client}
87	              </Link>
88	            )}
89	          </div>
90	          <div className="mt-2 flex items-center gap-1.5 text-[13px] text-ink-soft">
91	            <span className="inline-flex -space-x-1.5" aria-hidden>
92	              {others.slice(0, 8).map((s) => (
93	                <span
94	                  key={s.id}
95	                  className="inline-block size-2.5 rounded-full ring-2 ring-paper"
96	                  style={{ background: s.color }}
97	                />
98	              ))}
99	            </span>
100	            <span>
101	              {others.map((s) => s.name.split(" ")[0]).join(", ")}
102	              {others.length === 0 ? " solo test" : ""}
103	            </span>
104	          </div>
105	        </div>
106	        <div className="flex shrink-0 gap-2">
107	          <button
108	            onClick={() => setChatOpen(true)}
109	            aria-expanded={chatOpen}
110	            className="rounded-full bg-ink px-3.5 py-2 text-[13px] font-medium text-paper hover:opacity-90"
111	          >
112	            Chat with the call
113	          </button>
114	          <button
115	            onClick={copyAtCurrentTime}
116	            className="rounded-full border border-line bg-raised px-3.5 py-2 text-[13px] font-medium text-ink-soft hover:border-ink-soft hover:text-ink"
117	          >
118	            {copiedLink ? "Link copied" : "Copy link to this moment"}
119	          </button>
120	        </div>
121	      </div>
122	
123	      {/* chat dock — a right sidebar that overlays the transcript while open */}
124	      {chatOpen && (
125	        <aside
126	          className="fixed bottom-0 right-0 top-0 z-40 flex w-[380px] max-w-[95vw] flex-col border-l border-line bg-paper shadow-[-12px_0_32px_rgba(27,30,36,0.10)]"
127	          aria-label="Chat with the call"
128	        >
129	          <div className="flex items-center justify-between border-b border-line px-4 pt-[70px] pb-2.5">
130	            <div>
131	              <h2 className="text-[14px] font-semibold">Chat with the call</h2>
132	              <p className="text-[11.5px] text-ink-faint">answers are playable quotes, nothing invented</p>
133	            </div>
134	            <button
135	              onClick={() => setChatOpen(false)}
136	              className="rounded-full border border-line bg-raised px-3 py-1 text-[12.5px] text-ink-soft hover:border-ink-soft hover:text-ink"
137	            >
138	              Close
139	            </button>
140	          </div>
141	          <ChatPanel meeting={meeting} player={player} className="min-h-0 flex-1" />
142	        </aside>
143	      )}
144	
145	      {/* ── panes ──────────────────────────────────────────────────────── */}
146	      <div className="grid grid-cols-1 items-start gap-8 lg:grid-cols-[minmax(0,1fr)_400px] xl:grid-cols-[minmax(0,1fr)_440px]">
147	        <div className="min-w-0 space-y-6">
148	          <Player meeting={meeting} player={player} />
149	          <LeftPanel meeting={meeting} player={player} />
150	        </div>
