277	/**
278	 * Compose a full meeting from a booked spec: script lines get the attendee
279	 * names woven in, every artifact cites its line by substring anchor, so chat,
280	 * clips, dispatch and search all behave exactly as on seeded calls.
281	 */
282	export function composeMeeting(spec: DemoSpec, id: string): Meeting {
283	  const script = SCRIPTS_BODY[spec.script];
284	  const attendees = spec.attendees.filter((n) => n.trim());
285	  const speakers = [
286	    { id: "you", name: "You", color: "#0E7C86", self: true },
287	    ...attendees.map((att, i) => ({
288	      id: `g${i}`,
289	      name: att.includes("(") ? att : att,
290	      color: GUEST_COLORS[i % GUEST_COLORS.length],
291	    })),
292	  ];
293	  // a script line meant for a missing attendee falls to the first guest
294	  const resolve = (sp: number | "self") =>
295	    sp === "self" ? "you" : `g${Math.min(sp, Math.max(0, attendees.length - 1))}`;
296	
297	  // transcript with {A0}/{A1} woven into the attendee's first name
298	  const filled = script.lines.map((l) => ({
299	    sp: l.sp,
300	    text: l.text.replace(/\{A0\}/g, attendees[0] ?? "there").replace(/\{A1\}/g, attendees[1] ?? attendees[0] ?? "your first attendee"),
301	  }));
302	
303	  // timestamps follow the same cadence as the seed builder (~2.6 words/sec)
304	  let t = 0;
305	  const transcript: Utterance[] = filled.map((l) => {
306	    const speaker = resolve(l.sp);
307	    const words = l.text.trim().split(/\s+/).length;
308	    const dur = Math.max(1.8, Math.round((words / 2.6) * 10) / 10);
309	    const u = { t: Math.round(t), dur, speaker, text: l.text };
310	    t += dur + 0.9;
311	    return u;
312	  });
313	  const end = Math.round(t);
314	
315	  const at = (sub: string) => {
316	    const u = transcript.find((x) => x.text.includes(sub));
317	    return u ? u.t : -1;
318	  };
319	
320	  const first = (n: string) => n.trim().split(/\s+/)[0];
321	  const a0 = attendees[0] ?? "the attendee";
322	
323	  const gist = script.draft.gist
324	    .replace(/\{A0\}/g, first(a0))
325	    .replace(/\{A1\}/g, attendees[1] ? first(attendees[1]) : first(a0));
326	
327	  const summary = {
328	    template: "standard",
329	    gist,
330	    sections: script.draft.sections.map((sec) => ({
331	      heading: sec.heading,
332	      bullets: sec.bullets.map((bl) => {
333	        const t0 = at(bl.sub);
334	        return {
335	          text: bl.text.replace(/\{A0\}/g, first(a0)).replace(/\{A1\}/g, attendees[1] ? first(attendees[1]) : first(a0)),
336	          cite: t0,
337	        };
338	      }),
339	    })),
340	  };
341	
342	  const highlights = script.draft.highlights.map((h, i) => ({
343	    id: `hd-${id}-${i + 1}`,
344	    at: at(h.sub),
345	    title: h.title,
346	    tag: h.tag,
347	    note: h.note,
348	  }));
349	
350	  const actionItems = script.draft.actions.map((a, i) => {
351	    const owner = a.owner === "self" ? "You" : attendees[a.owner] ?? a0;
352	    const due = new Date(spec.startedAt);
353	    due.setDate(due.getDate() + a.dueIn);
354	    return {
355	      id: `ad-${id}-${i + 1}`,
356	      ownerName: owner,
357	      text: a.text.replace(/\{A0\}/g, first(a0)).replace(/\{A1\}/g, attendees[1] ?? a0),
358	      due: due.toISOString().slice(0, 10),
359	      cite: at(a.sub),
360	    };
361	  });
362	
363	  const email = [
364	    `Hi all —`,
365	    ``,
366	    `Quick recap of ${spec.title.toLowerCase()} from ${new Date(spec.startedAt).toLocaleDateString("en-US", { weekday: "long", month: "short", day: "numeric" })}:`,
367	    ``,
368	    gist,
369	    ``,
370	    `Action items:`,
371	    ``,
372	    ...actionItems.map((a) => `- ${a.text} (${a.ownerName})`),
373	    ``,
374	    `Recording and full transcript shared in Minutes.`,
375	    `Anything I got wrong or missed, reply to this note.`,
376	    `— Sent from Minutes`,
377	  ].join("\n");
378	
379	  return {
380	    id,
381	    title: spec.title,
382	    platform: spec.platform,
383	    startedAt: spec.startedAt,
384	    duration: end + 20,
385	    captureMode: spec.captureMode,
386	    status: "recorded",
387	    speakers,
388	    transcript,
389	    highlights,
390	    actionItems,
391	    summaries: { standard: summary },
392	    defaultTemplate: "standard",
393	    emailDraft: email,
394	  };
395	}
396	
397	/** The Upcoming row the armed-list sections render for a booked call. */
398	export function demoEventUpcoming(e: DemoEvent): Upcoming {
399	  return {
400	    id: e.id,
401	    title: e.spec.title,
402	    platform: e.spec.platform,
403	    startedAt: e.spec.startedAt,
404	    attendees: ["You", ...e.spec.attendees],
405	    captureMode: e.spec.captureMode,
406	  };
407	}

