              onSubmit={(e) => {
                e.preventDefault();
                feed();
              }}
              className="mt-2.5 flex gap-2"
            >
              <input
                ref={inputRef}
                value={text}
                onChange={(e) => setText(e.target.value)}
                placeholder={
                  sp === "self"
                    ? "What you're saying… then Enter to feed the scribe"
                    : `What ${nameOf(sp)} says… then Enter`
                }
                aria-label="Feed the scribe"
                className="min-w-0 flex-1 rounded-full border border-line bg-paper px-4 py-2 text-[14px] focus:outline-none focus:border-ink-soft"
              />
              <button
                type="submit"
                className="shrink-0 rounded-full bg-ink px-4 py-2 text-[13.5px] font-medium text-paper hover:opacity-90"
              >
                Feed
              </button>
            </form>
          </div>

          {/* transcript the scribe is writing */}
          <div ref={listRef} className="pane mt-4 h-64 overflow-y-auto" aria-label="Streaming transcript">
            {feeds.length === 0 ? (
              <p className="px-4 pt-14 text-center text-[13px] text-ink-faint">
                The scribe is listening — feed the first line of the call above.
              </p>
            ) : (
              <ul>
                {feeds.map((l, i) => {
                  const s = speakers.find((x) => (l.sp === "self") === !!x.self);
                  return (
                    <li key={i} className="border-b border-line-soft px-4 py-2.5">
                      <div className="mb-0.5 flex items-baseline gap-2">
                        <span className="text-[12.5px] font-semibold" style={{ color: s?.self ? undefined : s?.color }}>
                          {l.sp === "self" ? "You" : nameOf(l.sp)}
                        </span>
                        <span className="font-mono text-[11px] text-ink-faint">{mmss(i * 7)}</span>
                      </div>
                      <p className="text-[14px] leading-relaxed text-ink-soft">{l.text}</p>
                    </li>
                  );
                })}
              </ul>
            )}
          </div>
          <p className="mt-2 text-right text-[12px] text-ink-faint">
            capture simulation, ~{SPEED}× clock — type or paste the call as it happens
          </p>
        </div>
      )}

      {phase === "done" && preview && (
        <div>
          <div className="pane flex items-center gap-3 px-4 py-3">
            <span className="rec-dot size-2 rounded-full bg-record" aria-hidden />
            <span className="text-[14px] font-medium">Call ended</span>
            <span className="font-mono text-[13px] tabular-nums text-ink-faint">
              {hms(Math.round(simSec))} captured
            </span>
          </div>
          <div className="pane mt-4 p-5">
            <p className="eyebrow mb-2">Minutes wrote, as the call ended</p>
            <p className="font-[family-name:var(--font-display)] text-xl leading-snug">
              {preview.summary.gist}
            </p>
            <ul className="mt-4 space-y-2.5">
              {preview.summary.sections[0]?.bullets.map((b, i) => (
                <li key={i} className="flex gap-2.5 text-[14px] leading-relaxed">
                  <span className="shrink-0 rounded bg-record-soft px-1 font-mono text-[11.5px] font-medium text-record">
                    [{mmss(b.cite)}]
                  </span>
                  {b.text}
                </li>
              ))}
            </ul>
            {preview.actionItems.length > 0 && (
              <div className="mt-5 border-t border-line pt-4">
                <p className="eyebrow mb-2">Actions</p>
                <ul className="space-y-1.5">
                  {preview.actionItems.map((a) => (
                    <li key={a.id} className="text-[14px] text-ink-soft">
                      <span className="font-medium text-ink">{a.ownerName}</span> — {a.text}
                    </li>
                  ))}
                </ul>
              </div>
            )}
          </div>
          <div className="mt-5 flex flex-wrap items-center gap-3">
            <Link
              href={`/m/${event.id}`}
              className="rounded-full bg-ink px-5 py-2.5 text-[14px] font-medium text-paper hover:opacity-90"
            >
              Open the full meeting →
            </Link>
            <Link href="/" className="text-[13.5px] text-ink-soft hover:text-ink">
              Back to meetings
            </Link>
          </div>
          <p className="mt-4 text-[12.5px] text-ink-faint">
            The extraction is heuristic in this build — now live in the meeting with playback,
            chat, clips and dispatch, all citing your words.
          </p>
        </div>
      )}
    </div>
  );
}

