"use client";

import { clearDemo, demoEventUpcoming, downloadIcs, loadDemoStore } from "@/lib/demo";
import { fmtDate, fmtTime, hms } from "@/lib/time";
import Link from "next/link";
import { useEffect, useState } from "react";

/**
 * Booked-in-this-browser sections of the meetings page: armed bookings join
 * the seeded armed list, recorded bookings form their own section. Rendered
 * client-side only — nothing here exists on the server.
 */

function useBooked() {
  const [ready, setReady] = useState(false);
  useEffect(() => setReady(true), []);
  return ready ? loadDemoStore() : { events: [], meetings: [] };
}

export function DemoArmedSection() {
  const booked = useBooked();
  const armed = booked.events.filter((e) => e.status === "armed");
  if (armed.length === 0) return null;
  return (
    <section aria-label="Booked in this browser" className="mb-10">
      <h2 className="eyebrow mb-3">Armed — booked in this browser</h2>
      <ul className="pane divide-y divide-line-soft">
        {armed.map((e) => {
          const u = demoEventUpcoming(e);
          return (
            <li key={e.id} className="flex items-center gap-4 px-4 py-3">
              <span aria-hidden className="rec-dot size-2 rounded-full bg-record opacity-60" />
              <div className="min-w-0 flex-1">
                <Link
                  href={`/live/${e.id}`}
                  className="text-[15px] font-medium hover:text-record hover:underline underline-offset-2"
                >
                  {e.spec.title}
                </Link>
                <span className="ml-2 text-[13px] text-ink-soft">
                  {u.attendees.length > 1 && (
                    <span
                      title={u.attendees.slice(1).join(", ")}
                      className="mr-1 inline-flex -space-x-1.5 align-middle"
                      aria-hidden
                    >
                      {u.attendees.slice(1, 5).map((_, i) => (
                        <span key={i} className="inline-block size-2.5 rounded-full ring-2 ring-raised" style={{ background: "#c4c0b4" }} />
                      ))}
                    </span>
                  )}
                  {e.spec.platform} · {fmtDate(u.startedAt)} {fmtTime(u.startedAt)}
                  {e.spec.attendees.some((a) => a.email) && (
                    <span
                      title={e.spec.attendees.filter((a) => a.email).map((a) => `${a.name}: ${a.email}`).join("\n")}
                      className="ml-1.5 text-ink-faint"
                    >
                      · {e.spec.attendees.filter((a) => a.email).length} email
                      {e.spec.attendees.filter((a) => a.email).length === 1 ? "" : "s"}
                    </span>
                  )}
                </span>
              </div>
              <button
                onClick={() => downloadIcs(e)}
                className="shrink-0 rounded-full border border-line px-2.5 py-1 text-[11.5px] font-medium text-ink-soft hover:border-ink-soft hover:text-ink"
                title="Download this booking as a .ics with the attendees' emails — add it to your real calendar"
              >
                .ics
              </button>
              <span
                className={
                  "shrink-0 rounded-full px-2.5 py-1 text-xs font-medium " +
                  (e.spec.captureMode === "bot" ? "bg-line-soft text-ink-soft" : "bg-ok-soft text-ok")
                }
              >
                {e.spec.captureMode === "bot" ? "bot joins" : "bot-free capture"}
              </span>
            </li>
          );
        })}
      </ul>
      <p className="mt-2 text-[13px] text-ink-faint">
        Booked here, so these stay in this browser only.
      </p>
    </section>
  );
}

export function DemoRecordedSection() {
  const booked = useBooked();
  if (booked.meetings.length === 0) return null;

  return (
    <section aria-label="Booked calls" className="mb-10">
      <div className="mb-3 flex items-baseline justify-between gap-4">
        <h2 className="eyebrow">Booked calls — completed here</h2>
        <button
          onClick={() => clearDemo()}
          className="shrink-0 text-[12.5px] text-ink-faint underline underline-offset-2 hover:text-record"
        >
          Forget these (clears the browser store)
        </button>
      </div>
      <ul className="pane divide-y divide-line">
        {booked.meetings.map((m) => (
          <li key={m.id}>
            <Link href={`/m/${m.id}`} className="group flex items-center gap-4 px-4 py-3.5 hover:bg-line-soft/40">
              <div className="min-w-0 flex-1">
                <h3 className="truncate font-[family-name:var(--font-display)] text-[16.5px] font-medium tracking-tight group-hover:underline decoration-line-soft decoration-2 underline-offset-4">
                  {m.title}
                </h3>
                <p className="mt-0.5 flex items-center gap-2 text-[12.5px] text-ink-soft">
                  {fmtDate(m.startedAt)} {fmtTime(m.startedAt)} · {hms(m.duration)} ·{" "}
                  {m.actionItems.length} action item{m.actionItems.length === 1 ? "" : "s"} ·{" "}
                  {m.platform}
                </p>
              </div>
              <span className="shrink-0 rounded-full bg-ok-soft px-2.5 py-0.5 text-[11.5px] font-medium text-ok">
                {m.captureMode === "bot" ? "bot recorded" : "bot-free capture"}
              </span>
              <span className="hidden shrink-0 text-[13px] text-ink-faint group-hover:text-ink sm:block">
                Open ↗
              </span>
            </Link>
          </li>
        ))}
      </ul>
    </section>
  );
}

"use client";

import { composeMeeting, demoEventUpcoming, loadDemoStore, recordBooking, speakersOf } from "@/lib/demo";
import { LiveCapture } from "@/components/live/LiveCapture";
import { OwnCapture } from "@/components/demo/OwnCapture";
import Link from "next/link";
import { useEffect, useState } from "react";

/**
 * Capture simulation for a call booked in this browser — the booking's spec
 * lives in localStorage. Scripted calls replay their walkthrough; "your own"
 * calls hand control to the scribe composer (OwnCapture). Both record the
 * meeting when the simulated call ends.
 */
export function LocalLiveCapture({ id }: { id: string }) {
  const [state, setState] = useState<"loading" | "found" | "missing">("loading");
  const [ev, setEv] = useState<ReturnType<typeof loadDemoStore>["events"][number] | null>(null);

  useEffect(() => {
    const found = loadDemoStore().events.find((e) => e.id === id);
    if (found) {
      setEv(found);
      setState("found");
    } else {
      setState("missing");
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [id]);

  if (state === "missing")
    return (
      <div className="mx-auto max-w-3xl px-4 pt-14">
        <div className="pane p-6">
          <h1 className="font-[family-name:var(--font-display)] text-2xl font-medium">
            This booking isn&rsquo;t in this browser
          </h1>
          <p className="mt-2 text-[14.5px] leading-relaxed text-ink-soft">
            Booked calls live in the browser that booked them (this build has no database).{" "}
            <Link href="/book" className="underline underline-offset-2">
              Book this one here
            </Link>{" "}
            and the capture run will follow.
          </p>
          <Link href="/" className="mt-4 inline-block text-[13.5px] text-ink-soft hover:text-ink">
            Back to meetings
          </Link>
        </div>
      </div>
    );

  if (state !== "found" || !ev) return null;

  if (ev.spec.script === "blank")
    return (
      <OwnCapture
        booking={ev}
        speakers={speakersOf(ev.spec)}
        onDone={(feeds) => recordBooking(ev.id, feeds)}
      />
    );

  return (
    <LiveCapture
      event={demoEventUpcoming(ev)}
      meeting={composeMeeting(ev.spec, ev.id)}
      onDone={() => recordBooking(ev.id)}
    />
  );
}

"use client";

import type { Meeting } from "@/lib/model";
import { extractArtifacts } from "@/lib/extract";
import { demoEventUpcoming, downloadIcs, type DemoEvent, type FeedLine } from "@/lib/demo";
import { mmss, fmtTime, hms } from "@/lib/time";
import Link from "next/link";
import { useEffect, useMemo, useRef, useState } from "react";

const SPEED = 20;

/**
 * Live capture for a call booked as "your own" — no walkthrough script. The
 * scribe listens and you feed what's said (type or paste it as it happens);
 * Minutes transcribes, and on the call end extracts the summary, action items
 * and highlights it would write for any call, every line citing the moment.
 */
export function OwnCapture({
  booking,
  speakers,
  onDone,
}: {
  booking: DemoEvent;
  /** [You, ...attendees] — a FeedLine's sp indexes into this */
  speakers: Meeting["speakers"];
  onDone: (feeds: FeedLine[]) => void;
}) {
  const event = demoEventUpcoming(booking);
  const [phase, setPhase] = useState<"armed" | "live" | "done">("armed");
  const [simSec, setSimSec] = useState(0);
  const [feeds, setFeeds] = useState<FeedLine[]>([]);
  const [sp, setSp] = useState<number | "self">(0);
  const [text, setText] = useState("");
  const listRef = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (phase !== "live") return;
    const timer = setInterval(() => setSimSec((s) => s + SPEED / 2), 500);
    return () => clearInterval(timer);
  }, [phase]);

  useEffect(() => {
    listRef.current?.scrollTo({ top: listRef.current.scrollHeight, behavior: "smooth" });
  }, [feeds]);

  function feed() {
    const clean = text.trim();
    if (!clean) return;
    setFeeds((f) => [...f, { sp, text: clean }]);
    setText("");
    inputRef.current?.focus();
  }

  const words = useMemo(
    () => feeds.reduce((n, l) => n + l.text.trim().split(/\s+/).length, 0),
    [feeds]
  );

  // the extraction Minutes would run — computed live so the done pane shows it
  const fedTimes = useMemo(() => {
    const out: number[] = [];
    let t = 0;
    for (const l of feeds) {
      out.push(Math.round(t));
      const w = l.text.trim().split(/\s+/).length;
      t += Math.max(1.6, Math.round((w / 2.6) * 10) / 10) + 0.9;
    }
    return out;
  }, [feeds]);

  const preview = useMemo(() => {
    if (feeds.length === 0) return null;
    let t = 0;
    const transcript = feeds.map((l) => {
      const words = l.text.trim().split(/\s+/).length;
      const dur = Math.max(1.6, Math.round((words / 2.6) * 10) / 10);
      const speaker = l.sp === "self" ? "you" : `g${Math.min(l.sp, Math.max(0, speakers.length - 2))}`;
      const u = { t: Math.round(t), dur, speaker, text: l.text.trim() };
      t += dur + 0.9;
      return u;
    });
    return extractArtifacts(transcript, {
      idPrefix: "preview",
      nameOf: (sid) => speakers.find((s) => s.id === sid)?.name ?? sid,
    });
  }, [feeds, speakers]);

  function endNow() {
    if (feeds.length === 0) return;
    onDone(feeds);
    setPhase("done");
  }

  const nameOf = (spIdx: number | "self") =>
    speakers.find((s) => (spIdx === "self") === !!s.self)?.name ?? "?";

  return (
    <div className="mx-auto max-w-3xl px-4 pb-16 pt-8 sm:px-6">
      {/* ── header ─────────────────────────────────────────────────── */}
      <div className="mb-5 flex flex-wrap items-start justify-between gap-3">
        <div>
          <p className="eyebrow mb-1">
            {event.platform} · starts {fmtTime(event.startedAt)}
          </p>
          <h1 className="font-[family-name:var(--font-display)] text-3xl font-medium tracking-tight">
            {event.title}
          </h1>
        </div>
        <span
          className={
            "rounded-full px-2.5 py-1 text-[12.5px] font-medium " +
            (event.captureMode === "bot"
              ? "bg-line-soft text-ink-soft"
              : "bg-ok-soft text-ok")
          }
        >
          {event.captureMode === "bot" ? "minutes bot joins" : "bot-free — captures locally"}
        </span>
      </div>

      {phase === "armed" && (
        <div className="pane p-6">
          <p className="text-[15px] leading-relaxed text-ink-soft">
            Minutes is armed for this call — it&rsquo;s yours, not a walkthrough. When the meeting
            starts, the scribe listens and you feed what&rsquo;s said; Minutes writes the
            summary, action items and highlights from your words, every line cited.
          </p>
          <div className="mt-5 flex flex-wrap items-center gap-3">
            <button
              onClick={() => setPhase("live")}
              className="rounded-full bg-ink px-5 py-2.5 text-[14px] font-medium text-paper hover:opacity-90"
            >
              ▶ Start the call
            </button>
            <button
              onClick={() => downloadIcs(booking)}
              className="rounded-full border border-line bg-raised px-4 py-2.5 text-[13.5px] font-medium text-ink-soft hover:border-ink-soft hover:text-ink"
              title="Download this booking as a calendar .ics file with the attendees' emails"
            >
              Add to my real calendar (.ics)
            </button>
            <Link href="/" className="text-[13.5px] text-ink-soft hover:text-ink">
              Back to meetings
            </Link>
          </div>
          <p className="mt-4 text-[12.5px] text-ink-faint">
            Attendees: {speakers.filter((s) => !s.self).map((s) => s.name).join(", ") || "none yet"}. In
            this build nothing joins Zoom — the capture layer is this scribe.
          </p>
        </div>
      )}

      {phase === "live" && (
        <div>
          {/* status bar */}
          <div className="pane flex flex-wrap items-center gap-x-4 gap-y-1 px-4 py-3">
            <span className="flex items-center gap-2 text-[13.5px] font-medium">
              <span className="rec-dot size-2 rounded-full bg-record" aria-hidden />
              Capturing
            </span>
            <span className="font-mono text-[13.5px] tabular-nums text-ink">
              {mmss(Math.floor(simSec))}
            </span>
            <span className="text-[12.5px] text-ink-faint">
              {words.toLocaleString()} words · {feeds.length} turn{feeds.length === 1 ? "" : "s"} fed
            </span>
            <button
              onClick={endNow}
              disabled={feeds.length === 0}
              className="ml-auto rounded-full border border-line bg-raised px-3.5 py-1.5 text-[12.5px] font-medium text-ink-soft hover:border-ink-soft hover:text-ink disabled:opacity-40"
              title={feeds.length === 0 ? "Feed at least one line first" : "Minutes writes the summary"}
            >
              End the call — Minutes writes it ⏭
            </button>
          </div>

          {/* scribe composer */}
          <div className="pane mt-4 px-4 py-3">
            <div className="flex flex-wrap items-center gap-1.5">
              <span className="mr-1 text-[12px] text-ink-faint">Who&rsquo;s speaking:</span>
              {speakers.map((s) => {
                const isSelf = !!s.self;
                const idx: number | "self" = isSelf ? "self" : Number(s.id.replace("g", "")) || 0;
                return (
                  <button
                    key={s.id}
                    onClick={() => setSp(idx)}
                    aria-pressed={sp === idx}
                    className={
                      "rounded-full px-3 py-1 text-[12.5px] font-medium " +
                      (sp === idx
                        ? "text-paper"
                        : "border border-line bg-raised text-ink-soft hover:text-ink")
                    }
                    style={sp === idx ? { background: s.color } : { boxShadow: `inset 3px 0 0 ${s.color}` }}
                  >
                    {s.name}
                  </button>
                );
              })}
            </div>
            <form
              onSubmit={(e) => {
                e.preventDefault();
                feed();
              }}
              className="mt-2.5 flex gap-2"
            >
              <input
                ref={inputRef}
                value={text}
                onChange={(e) => setText(e.target.value)}
                placeholder={
                  sp === "self"
                    ? "What you're saying… then Enter to feed the scribe"
                    : `What ${nameOf(sp)} says… then Enter`
                }
                aria-label="Feed the scribe"
                className="min-w-0 flex-1 rounded-full border border-line bg-paper px-4 py-2 text-[14px] focus:outline-none focus:border-ink-soft"
              />
              <button
                type="submit"
                className="shrink-0 rounded-full bg-ink px-4 py-2 text-[13.5px] font-medium text-paper hover:opacity-90"
              >
                Feed
              </button>
            </form>
          </div>

          {/* transcript the scribe is writing (timestamps follow Minutes' cadence) */}
          <div ref={listRef} className="pane mt-4 h-64 overflow-y-auto" aria-label="Streaming transcript">
            {feeds.length === 0 ? (
              <p className="px-4 pt-14 text-center text-[13px] text-ink-faint">
                The scribe is listening — feed the first line of the call above.
              </p>
            ) : (
              <ul>
                {feeds.map((l, i) => {
                  const s = speakers.find((x) => (l.sp === "self") === !!x.self);
                  const fedAt = fedTimes[i] ?? 0;
                  return (
                    <li key={i} className="border-b border-line-soft px-4 py-2.5">
                      <div className="mb-0.5 flex items-baseline gap-2">
                        <span className="text-[12.5px] font-semibold" style={{ color: s?.self ? undefined : s?.color }}>
                          {l.sp === "self" ? "You" : nameOf(l.sp)}
                        </span>
