"use client";

import type { Meeting } from "@/lib/model";
import { extractArtifacts } from "@/lib/extract";
import { demoEventUpcoming, type DemoEvent, type FeedLine } from "@/lib/demo";
import { demoIdForRealEvent, loadDemoStore, recordBooking } from "@/lib/demo";
import { loadGCal } from "@/lib/gcal";
import { CaptureSummary } from "@/components/demo/CaptureSummary";
import { fmtTime, hms, mmss } from "@/lib/time";
import Link from "next/link";
import { useEffect, useRef, useState } from "react";

/**
 * REAL capture, for a real Google Meet call: the user is in the call, Minutes
 * listens to the shared Meet tab's audio in this browser and transcribes it
 * live (browser speech recognition), tagging each utterance with the speaker
 * chip you've selected. On stop, the same extraction as any call runs and the
 * full meeting — playback, chat, clips, dispatch — is built from the real
 * words. No server sees the audio; nothing joins Meet headlessly (a browser
 * page can't, and Google blocks bots at the door anyway).
 */

// minimal structural types for the Web Speech API (still non-standard in lib.dom)
type SRAlternative = { transcript: string };
type SRResultItem = { isFinal: boolean; 0: SRAlternative; length: number };
type SREvent = { resultIndex: number; results: { length: number; [index: number]: SRResultItem } };
type SRLike = {
  continuous: boolean;
  interimResults: boolean;
  lang: string;
  start(): void;
  stop(): void;
  onresult: ((e: SREvent) => void) | null;
  onerror: ((e: { error: string }) => void) | null;
  onend: (() => void) | null;
};
type SRCtor = new () => SRLike;

function speechCtor(): SRCtor | null {
  const w = window as unknown as { SpeechRecognition?: SRCtor; webkitSpeechRecognition?: SRCtor };
  return w.SpeechRecognition ?? w.webkitSpeechRecognition ?? null;
}

export function RealCapture({ id }: { id: string }) {
  const [state, setState] = useState<"loading" | "locked" | "found" | "missing">("loading");
  const [ev, setEv] = useState<DemoEvent | null>(null);
  const [phase, setPhase] = useState<"armed" | "live" | "done">("armed");
  const [recording, setRecording] = useState(false);
  const [simSec, setSimSec] = useState(0);
  const [feeds, setFeeds] = useState<FeedLine[]>([]);
  const [interim, setInterim] = useState("");
  const [level, setLevel] = useState(0);
  const [sttError, setSttError] = useState<string | null>(null);
  const [sp, setSp] = useState<number | "self">(0);
  const [meetLink, setMeetLink] = useState<string | null>(null);
  const [result, setResult] = useState<Meeting | null>(null);

  const recRef = useRef<SRLike | null>(null);
  const streamRef = useRef<MediaStream | null>(null);
  const spRef = useRef<number | "self">(0);
  const listRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    spRef.current = sp;
  }, [sp]);

  useEffect(() => {
    const mapId = id.startsWith("real-") ? id.slice("real-".length) : id;
    const demoId = demoIdForRealEvent(mapId);
    if (!demoId) {
      setState("missing");
      return;
    }
    const found = loadDemoStore().events.find((e) => e.id === demoId);
    if (found) {
      setEv(found);
      setState("found");
    } else {
      setState("locked"); // the booking exists but not in this browser
    }
  }, [id]);

  useEffect(() => {
    listRef.current?.scrollTo({ top: listRef.current.scrollHeight });
  }, [feeds, interim]);

  // real clock while capturing audio
  useEffect(() => {
    if (!recording) return;
    const started = Date.now();
    const timer = setInterval(() => setSimSec((Date.now() - started) / 1000), 500);
    return () => clearInterval(timer);
  }, [recording]);

  const words = useMemo(
    () => feeds.reduce((n, l) => n + l.text.trim().split(/\s+/).length, 0),
    [feeds],
  );

  const speakers = ev ? (ev as DemoEvent & { meetLink?: string }).meetLink : null;

  async function startCapture() {
    if (!ev) return;
    setSttError(null);
    // 1. tab/screen audio — the honest in-browser path; the user picks the Meet tab
    let stream: MediaStream;
    try {
      stream = await navigator.mediaDevices.getDisplayMedia({
        video: true,
        audio: { echoCancellation: false, noiseSuppression: false, autoGainControl: false },
      });
    } catch {
      setSttError("Tab sharing was cancelled or is unavailable — Minutes needs the Meet tab with “share tab audio”.");
      return;
    }
    streamRef.current = stream;
    stream.getVideoTracks().forEach((t) => t.stop()); // Minutes only needs the audio
    setRecording(true);
    setPhase("live");

    // 2. live level meter so an audio-less share is visible immediately
    try {
      const ctx = new AudioContext();
      const src = ctx.createMediaStreamSource(stream);
      const analyser = ctx.createAnalyser();
      src.connect(analyser);
      const data = new Uint8Array(analyser.frequencyBinCount);
      const read = () => {
        analyser.getByteTimeDomainData(data);
        let sum = 0;
        for (let i = 0; i < data.length; i++) {
          const v = (data[i] - 128) / 128;
          sum += v * v;
        }
        setLevel(Math.min(1, Math.sqrt(sum / data.length) * 4));
        raf = requestAnimationFrame(read);
      };
      let raf = requestAnimationFrame(read);
    } catch {
      /* meter is best-effort */
    }

    // 3. browser speech recognition on the tab audio
    const Ctor = speechCtor();
    if (!Ctor) {
      setSttError("This browser has no speech recognition — use Chrome or Edge to capture a real call.");
      return;
    }
    const rec = new Ctor();
    rec.continuous = true;
    rec.interimResults = true;
    rec.lang = navigator.language || "en-US";
    rec.onresult = (e) => {
      let draft = "";
      for (let i = e.resultIndex; i < e.results.length; i++) {
        const r = e.results[i];
        const text = r[0].transcript.trim();
        if (!text) continue;
        if (r.isFinal) {
          setFeeds((f) => [...f, { sp: spRef.current, text, t: (Date.now() - startedAt.current) / 1000 }]);
          draft = "";
        } else {
          draft += " " + text;
        }
      }
      setInterim(draft.trim());
    };
    rec.onerror = (e) => {
      if (e.error === "not-allowed" || e.error === "service-not-allowed") {
        setSttError("Recognition was refused — grant the mic/audio permission and start again.");
      } else if (e.error !== "no-speech" && e.error !== "aborted") {
        setSttError(`Recognition hiccup: ${e.error} — still trying.`);
      }
    };
    // Chrome stops long sessions on its own — start again while recording holds
    rec.onend = () => {
      if (recRecording.current) {
        try {
          rec.start();
        } catch {
          /* already restarting */
        }
      }
    };
    recRef.current = rec;
    try {
      rec.start();
    } catch {
      /* already started */
    }
  }

  // capture start time, real clock (refs work inside the onresult callback)
  const startedAt = useRef<number>(0);
  const recRecording = useRef<boolean>(false);
  useEffect(() => {
    recRecording.current = recording;
    if (recording) startedAt.current = Date.now();
  }, [recording]);

  function stopCapture() {
    if (feeds.length === 0 || !ev) return;
    recRecording.current = false;
    try {
      recRef.current?.stop();
    } catch {
      /* already stopped */
    }
    streamRef.current?.getTracks().forEach((t) => t.stop());
    setRecording(false);
    const meeting = recordBooking(ev.id, feeds);
    if (meeting) setResult(meeting);
    setPhase("done");
  }

  // ── states ────────────────────────────────────────────────────────────────

  if (state === "loading") return null;

  if (state === "missing" || state === "locked")
    return (
      <div className="mx-auto max-w-3xl px-4 pt-14">
        <div className="pane p-6">
          <h1 className="font-[family-name:var(--font-display)] text-2xl font-medium">
            This real event isn&rsquo;t armed in this browser
          </h1>
          <p className="mt-2 text-[14.5px] leading-relaxed text-ink-soft">
            Arm it from <Link href="/book" className="underline underline-offset-2">the booking page</Link>{" "}
            (connect Google Calendar → Arm Minutes on the event) — the armed link belongs to the
            browser that armed it.
          </p>
          <Link href="/" className="mt-4 inline-block text-[13.5px] text-ink-soft hover:text-ink">
            Back to meetings
          </Link>
        </div>
      </div>
    );

  if (!ev) return null;
  const event = demoEventUpcoming(ev);

  if (phase === "done" && result)
    return (
      <div className="mx-auto max-w-3xl px-4 pb-16 pt-8 sm:px-6">
        <CaptureSummary
          event={event}
          preview={result}
          capturedLabel={hms(Math.round(simSec))}
          subtitle="real call, transcribed in this browser"
        />
      </div>
    );

  const nameOf = (spIdx: number | "self") =>
    (ev.spec as unknown as { nameOf?: never }) ? undefined : undefined; // placeholder, fixed below

  return (
    <div className="mx-auto max-w-3xl px-4 pb-16 pt-8 sm:px-6">
      {/* ── header ─────────────────────────────────────────────────── */}
      <div className="mb-5 flex flex-wrap items-start justify-between gap-3">
        <div>
          <p className="eyebrow mb-1">
            {event.platform} · starts {fmtTime(event.startedAt)}
          </p>
          <h1 className="font-[family-name:var(--font-display)] text-3xl font-medium tracking-tight">
            {event.title}
          </h1>
        </div>
        <span className="rounded-full bg-record-soft px-2.5 py-1 text-[12.5px] font-medium text-record">
          real call — captured in this browser
        </span>
      </div>

      {phase === "armed" && (
        <div className="pane p-6">
          <p className="text-[15px] leading-relaxed text-ink-soft">
            Minutes is armed for the real {event.platform} call. Join the call in another tab,
            then start the capture here and pick <strong>that tab</strong> (with{" "}
            <em>share tab audio</em> on) — Minutes listens, transcribes live, and writes the
            minutes when you end the capture. Nothing joins Meet headlessly; this is the same
            system-audio path Fathom&rsquo;s desktop app takes, minus the desktop app.
          </p>
          <div className="mt-5 flex flex-wrap items-center gap-3">
            <button
              onClick={startCapture}
              className="rounded-full bg-ink px-5 py-2.5 text-[14px] font-medium text-paper hover:opacity-90"
            >
              ▶ Start capture
            </button>
            {meetLink && (
              <a
                href={meetLink}
                target="_blank"
                rel="noreferrer"
                className="rounded-full border border-line bg-raised px-4 py-2.5 text-[13.5px] font-medium text-ink-soft hover:border-ink-soft hover:text-ink"
              >
                Open the Google Meet call ↗
              </a>
            )}
            <Link href="/" className="text-[13.5px] text-ink-soft hover:text-ink">
              Back to meetings
            </Link>
          </div>
          <p className="mt-4 text-[12.5px] text-ink-faint">
            {speakersOfNames(ev).join(", ") || "No attendees booked."} · Best in Chrome/Edge · the
            event is on your real calendar.
          </p>
        </div>
      )}

      {phase === "live" && (
        <div>
          {/* status bar */}
          <div className="pane flex flex-wrap items-center gap-x-4 gap-y-1 px-4 py-3">
            <span className="flex items-center gap-2 text-[13.5px] font-medium">
              <span className="rec-dot size-2 rounded-full bg-record" aria-hidden />
              Capturing
            </span>
            <span className="font-mono text-[13.5px] tabular-nums text-ink">
              {mmss(Math.floor(simSec))}
            </span>
            {/* audio level — a dead bar means the tab was shared without audio */}
            <span className="flex items-center gap-2" title="Audio level from the shared tab">
              <span className="text-[12px] text-ink-faint">audio</span>
              <span className="h-1.5 w-20 overflow-hidden rounded-full bg-line-soft">
                <span
                  className="block h-full rounded-full bg-record transition-[width] duration-100"
                  style={{ width: `${Math.round(level * 100)}%` }}
                />
              </span>
            </span>
            <span className="text-[12.5px] text-ink-faint">
              {words.toLocaleString()} words · {feeds.length} turn{feeds.length === 1 ? "" : "s"}
            </span>
            <button
              onClick={stopCapture}
              disabled={feeds.length === 0}
