        const text = r[0].transcript.trim();
        if (!text) continue;
        if (r.isFinal) {
          setFeeds((f) => [...f, { sp: spRef.current, text, t: (Date.now() - startedAt.current) / 1000 }]);
          draft = "";
        } else {
          draft += " " + text;
        }
      }
      setInterim(draft.trim());
    };
    rec.onerror = (e) => {
      if (e.error === "not-allowed" || e.error === "service-not-allowed") {
        setSttError("Recognition was refused — grant the mic/audio permission and start again.");
      } else if (e.error !== "no-speech" && e.error !== "aborted") {
        setSttError(`Recognition hiccup: ${e.error} — still trying.`);
      }
    };
